export interface OSContext {
  sh: (cmd: string, opts?: any) => Promise<{ stdout: string; stderr: string; exitCode: number }>
  cwd: string
  env: Record<string, string>
  log: (msg: string) => void
  args: any
}

export default async function run(ctx: OSContext) {
  const { env, log, args } = ctx
  const host = env.SD_HOST || 'http://lotus:7860'

  let fullInput = ''
  if (typeof args === 'string') fullInput = args
  else if (args && typeof args.input === 'string') fullInput = args.input
  else if (args && typeof args.prompt === 'string') fullInput = args.prompt
  else if (args && Array.isArray(args.positional)) fullInput = args.positional.join(' ')
  else if (Array.isArray(args)) fullInput = args.join(' ')
  fullInput = fullInput.trim()

  // Extract file target if specified
  const fileMatch =
    fullInput.match(/(?:save(?:\s+it)?\s+as\s+|into\s+|to\s+)([a-zA-Z0-9_.-]+\.(?:png|jpg|jpeg))/i) ||
    fullInput.match(/([a-zA-Z0-9_.-]+\.(?:png|jpg|jpeg))/i)
  const outFile = fileMatch ? fileMatch[1] : (args?.output || 'output.png')

  // Clean prompt of directives
  const cleanPrompt =
    fullInput
      .replace(/generate\s+(an?\s+)?(image|picture|pic|photo)\s+of\s+/i, '')
      .replace(/(?:save(?:\s+it)?\s+as\s+|into\s+|to\s+)[a-zA-Z0-9_.-]+\.(?:png|jpg|jpeg)/i, '')
      .trim() || 'a majestic cat, photorealistic, 8k, detailed'

  log(`🎨 Generating image via ${host} [SDXL] for: "${cleanPrompt}"...`)

  try {
    const ctrl = new AbortController()
    const timeout = setTimeout(() => ctrl.abort(), 90000)
    const res = await fetch(`${host}/sdapi/v1/txt2img`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        prompt: cleanPrompt,
        steps: 25,
        width: 1024,
        height: 1024
      }),
      signal: ctrl.signal
    })
    clearTimeout(timeout)

    if (!res.ok) throw new Error(`HTTP ${res.status}: ${res.statusText}`)
    const json = (await res.json()) as { images?: string[] }
    if (!json.images || !json.images[0]) throw new Error('No image data returned from Stable Diffusion')

    await Bun.write(outFile, Buffer.from(json.images[0], 'base64'))
    log(`✔ Successfully saved generated image to: ${outFile}`)

    const isKittyOrGhostty = Boolean(
      process.env.KITTY_WINDOW_ID ||
        (process.env.TERM || '').includes('kitty') ||
        (process.env.TERM_PROGRAM || '').toLowerCase().includes('ghostty')
    )
    if (isKittyOrGhostty) {
      const b64 = json.images[0]
      const chunkSize = 4096
      for (let i = 0; i < b64.length; i += chunkSize) {
        const chunk = b64.slice(i, i + chunkSize)
        const isLast = i + chunkSize >= b64.length
        const m = isLast ? 0 : 1
        const header = i === 0 ? 'a=T,f=100,t=d,' : ''
        process.stdout.write(`\x1b_G${header}m=${m};${chunk}\x1b\\`)
      }
      process.stdout.write('\n')
    }

    return { success: true, outFile, prompt: cleanPrompt }
  } catch (err: any) {
    log(`❌ Image generation failed: ${err.message}`)
    throw err
  }
}

export interface OSContext {
  sh: (cmd: string, opts?: any) => Promise<{ stdout: string; stderr: string; exitCode: number }>
  cwd: string
  env: Record<string, string>
  log: (msg: string) => void
  args: any
}

export default async function run(ctx: OSContext) {
  const { sh, log, args } = ctx

  let location = ''
  if (typeof args === 'string') {
    const clean = args
      .replace(/^(what('s|\s+is)\s+the\s+weather(\s+in|\s+for)?|how('s|\s+is)\s+the\s+weather(\s+in|\s+for)?|weather(\s+in|\s+for)?|get\s+weather(\s+in|\s+for)?|acquire\s+the\s+weather\s+skill)\s*/i, '')
      .replace(/[?!.]+$/, '')
      .trim()
    location = clean
  } else if (args && typeof args === 'object') {
    location = args.location || args.city || args.input || ''
  }

  const locParam = location ? encodeURIComponent(location) : ''
  log(`🌤️ Fetching weather report${location ? ` for "${location}"` : ' for current location'}...`)

  // Try wttr.in format 3 for clean terminal summary
  const res = await sh(`curl -s --max-time 6 "wttr.in/${locParam}?format=%l:+%c+%t+(humidity:+%h,+wind:+%w)"`)
  if (res.exitCode === 0 && res.stdout.trim() && !res.stdout.includes('<!DOCTYPE')) {
    const output = res.stdout.trim()
    log(`\x1b[1;36m${output}\x1b[0m`)
    return { success: true, location: location || 'auto', weather: output }
  }

  // Fallback to 1-day compact summary
  const fallback = await sh(`curl -s --max-time 6 "wttr.in/${locParam}?0"`)
  if (fallback.exitCode === 0 && fallback.stdout.trim()) {
    console.log('\n' + fallback.stdout)
    return { success: true, location: location || 'auto', weather: fallback.stdout }
  }

  throw new Error('Weather service unavailable or network timeout.')
}

import fs from 'node:fs'
import path from 'node:path'
import os from 'node:os'

export interface OSContext {
  sh: (cmd: string, opts?: any) => Promise<{ stdout: string; stderr: string; exitCode: number }>
  cwd: string
  env: Record<string, string>
  log: (msg: string) => void
  args: any
}

export default async function run(ctx: OSContext) {
  const { sh, log, args } = ctx

  let inputName = ''
  let inputDesc = ''
  let tags: string[] = ['custom', 'skill']

  if (typeof args === 'string') {
    const raw = args.replace(/^create\s+skill\s+/i, '').trim()
    inputName = raw.split(/\s+/)[0] || 'custom-skill'
    inputDesc = raw || 'Custom synthesized operational skill'
  } else if (args && typeof args === 'object') {
    inputName = args.name || args.input || 'custom-skill'
    inputDesc = args.description || args.prompt || `Skill for ${inputName}`
    if (Array.isArray(args.tags)) tags = args.tags
  }

  const safeName = inputName.toLowerCase().replace(/[^a-z0-9_-]/g, '-').replace(/^-+|-+$/g, '') || 'custom-skill'
  log(`🛠️ Scaffolding skill bundle for: "${safeName}"...`)

  // Target directory inside user's local skills cache
  const targetDir = path.join(os.homedir(), '.config', 'ai-cli', 'skills', safeName)
  fs.mkdirSync(targetDir, { recursive: true })

  // 1. Generate skill.json
  const meta = {
    id: `skills/${safeName}`,
    name: safeName,
    title: safeName.replace(/-/g, ' ').replace(/\b\w/g, (l) => l.toUpperCase()),
    description: inputDesc,
    target: 'universal',
    tags: Array.from(new Set([safeName, ...tags])),
    safeToAutomate: true,
    requirements: {
      daemons: [],
      binaries: []
    },
    inputs: {
      query: { type: 'string', description: 'Input parameter for the skill' }
    },
    entrypoint: 'run.ts'
  }

  fs.writeFileSync(path.join(targetDir, 'skill.json'), JSON.stringify(meta, null, 2) + '\n', 'utf8')
  log(`  ➜ Created skill.json`)

  // 2. Generate run.ts
  const runCode = `export interface OSContext {
  sh: (cmd: string, opts?: any) => Promise<{ stdout: string; stderr: string; exitCode: number }>
  cwd: string
  env: Record<string, string>
  log: (msg: string) => void
  args: any
}

export default async function run(ctx: OSContext) {
  const { log, args, sh } = ctx
  log(\`Running skill "${safeName}" with args: \${JSON.stringify(args)}\`)
  return { success: true, skill: "${safeName}", timestamp: new Date().toISOString() }
}
`
  fs.writeFileSync(path.join(targetDir, 'run.ts'), runCode, 'utf8')
  log(`  ➜ Created run.ts`)

  // 3. Generate skill.test.ts
  const testCode = `import { describe, it, expect } from 'bun:test'
import run from './run.ts'

describe('Skill: ${safeName}', () => {
  it('executes successfully and returns structured output', async () => {
    const logs: string[] = []
    const ctx = {
      sh: async () => ({ stdout: '', stderr: '', exitCode: 0 }),
      cwd: process.cwd(),
      env: {},
      log: (msg: string) => logs.push(msg),
      args: { test: true }
    }
    const res = await run(ctx)
    expect(res.success).toBe(true)
    expect(res.skill).toBe('${safeName}')
  })
})
`
  fs.writeFileSync(path.join(targetDir, 'skill.test.ts'), testCode, 'utf8')
  log(`  ➜ Created skill.test.ts`)

  // 4. Run verification test suite
  log(`🧪 Running deterministic verification test...`)
  const testRes = await sh(`bun test "${path.join(targetDir, 'skill.test.ts')}"`)
  if (testRes.exitCode !== 0) {
    log(`⚠️ Verification test failed:\n${testRes.stderr || testRes.stdout}`)
    throw new Error(`Generated skill test failed verification: ${testRes.stderr || testRes.stdout}`)
  }
  log(`✔ Skill "${safeName}" verified and tested successfully!`)

  return {
    success: true,
    skillId: meta.id,
    path: targetDir,
    meta,
    files: ['skill.json', 'run.ts', 'test.ts']
  }
}
